/* auto-assign card colors + budget breakdowns.
   PRICING (src/data/pricing.json, generated by scripts/reprice.mjs from live
   fares + researched hostel/food benchmarks) is the source of truth for cost
   and breakdown when it covers a trip; the literal cost above is the
   fallback for anything the generator has not priced yet. */
TRIPS.forEach((t, i) => {
  t.color = PALETTE[i % PALETTE.length];
  const p = PRICING[t.id];
  if (p) { t.cost = p.cost; t.breakdown = { ...p.breakdown }; }
  if (!t.breakdown) {
    const r = t.driveOnly ? [0.15, 0.35, 0.3, 0.2] : [0.45, 0.25, 0.18, 0.12];
    t.breakdown = {
      travel: Math.round((t.cost * r[0]) / 5) * 5, stay: Math.round((t.cost * r[1]) / 5) * 5,
      food: Math.round((t.cost * r[2]) / 5) * 5, fun: Math.round((t.cost * r[3]) / 5) * 5,
    };
    t.breakdown.fun = t.cost - t.breakdown.travel - t.breakdown.stay - t.breakdown.food;
  }
});
/* the CHEAPEST SEND badge follows the final numbers, not the hand-set flag */
{
  const min = TRIPS.reduce((a, t) => (t.cost < a.cost ? t : a), TRIPS[0]);
  TRIPS.forEach((t) => { t.cheapest = t === min; });
}
